INSERT INTO sat_questions (question_id, external_id, vault_id, disclosed_item_id, source, program, test_type, test_type_desc, domain, primary_class_cd, skill_cd, skill_desc, difficulty, score_band_range_cd, question_type, stimulus_html, stem_html, answer_options, correct_answer, answer_keys, rationale_html, correct_answer_extracted_from_rationale, image_count, parent_template_name, parent_template_id, template_cluster_id, template_cluster_name, origin, position, answer_style, section, raw_payload, created_date, updated_date) VALUES
    ($SATQ$faaf484f$SATQ$, $SATQ$26d3a088-7084-4cd3-9dbe-5cd93c6824be$SATQ$::uuid, $SATQ$14be10a5-7133-4769-a040-0d148eb4637b$SATQ$::uuid, NULL, $SATQ$qbank$SATQ$, $SATQ$SAT$SATQ$, 1, $SATQ$Reading and Writing$SATQ$, $SATQ$Information and Ideas$SATQ$, $SATQ$INI$SATQ$, $SATQ$COE$SATQ$, $SATQ$Command of Evidence$SATQ$, $SATQ$E$SATQ$, 1, $SATQ$mcq$SATQ$, $SATQ$<p><figure class="table"><table class="gdr"><caption style="caption-side: top;"><p style="text-align: center;">Percent of Residents of City Areas in Favor of Adding More Bike Paths</p></caption><thead><tr><th scope="col" style="text-align: center; vertical-align: bottom;">City Area</th><th scope="col" style="text-align: center; vertical-align: bottom;">Percent of area&rsquo;s residents in favor of adding more bike paths</th></tr></thead><tbody><tr><th scope="row" style="text-align: left;">North East</th><td style="text-align: center;">12%</td></tr><tr><th scope="row" style="text-align: left;">North Central</th><td style="text-align: center;">26%</td></tr><tr><th scope="row" style="text-align: left;">North West</th><td style="text-align: center;">46%</td></tr><tr><th scope="row" style="text-align: left;">South West</th><td style="text-align: center;">88%</td></tr><tr><th scope="row" style="text-align: left;">South Central</th><td style="text-align: center;">33%</td></tr></tbody></table></figure></p>
<p>A city&rsquo;s Parks and Recreation department is interested in providing residents with more opportunities for bicycling in their neighborhoods. They&rsquo;re considering adding more bike paths and conducted a survey to understand where demand for more bike paths is highest. The survey indicated the highest level of demand, with 88 percent of the residents interested in adding more bike paths, is in the city&rsquo;s <span aria-hidden="true">______</span><span class="sr-only">blank</span></p>$SATQ$, $SATQ$<p>Which choice most effectively uses data from the table to complete the statement?</p>$SATQ$, $SATQ$[{"id":"a29ebef1-7c8e-461e-89ce-9b70ed62876f","content":"<p>South West area.</p>"},{"id":"fd9d950c-0449-4582-ba99-7275bca6a8da","content":"<p>South Central area.</p>"},{"id":"4980bd22-dab1-4dda-835d-b63c86407216","content":"<p>North East area.</p>"},{"id":"6e9c6436-668e-4af6-b907-ec5312577d1e","content":"<p>North Central area.</p>"}]$SATQ$::jsonb, $SATQ$["A"]$SATQ$::jsonb, $SATQ$["a29ebef1-7c8e-461e-89ce-9b70ed62876f"]$SATQ$::jsonb, $SATQ$<p>Choice A is the best answer because it most effectively uses data from the table to complete the statement about the bike path survey. The table presents the percent of residents from five city areas who are in favor of adding more bike paths. With 88 percent of residents in favor of adding bike paths, the city&rsquo;s South West area has the highest level of demand.&nbsp;</p><p>Choice B is incorrect because, according to the data in the table, 33 percent of residents in the South Central area of the city are in favor of additional bike paths. The area of the city that has 88 percent of its surveyed residents in favor of additional bike paths will best complete the statement. Choice C is incorrect because, according to the data in the table, 12 percent of residents in the North East area of the city are in favor of additional bike paths. The area of the city that has 88 percent of its surveyed residents in favor of additional bike paths will best complete the statement. Choice D is incorrect because, according to the data in the table, 26 percent of residents in the North Central area of the city are in favor of additional bike paths. The area of the city that has 88 percent of its surveyed residents in favor of additional bike paths will best complete the statement. </p>$SATQ$, false, 0, $SATQ$OSP-KA-QUA-E007$SATQ$, $SATQ$$SATQ$, $SATQ$d06994b9-3661-4d3a-baa5-664c1f52056a$SATQ$::uuid, $SATQ$$SATQ$, $SATQ$proteus$SATQ$, $SATQ$0$SATQ$, NULL, NULL, $SATQ${"questionId":"faaf484f","external_id":"26d3a088-7084-4cd3-9dbe-5cd93c6824be","vaultid":"14be10a5-7133-4769-a040-0d148eb4637b","uId":"cbc65217-e0fa-4640-b137-641b82d346ba","program":"SAT","test_type":1,"test_type_desc":"Reading and Writing","primary_class_cd":"INI","domain":"Information and Ideas","skill_cd":"COE","skill_desc":"Command of Evidence","difficulty":"E","score_band_range_cd":1,"type":"mcq","stimulus":"<p><figure class=\"table\"><table class=\"gdr\"><caption style=\"caption-side: top;\"><p style=\"text-align: center;\">Percent of Residents of City Areas in Favor of Adding More Bike Paths</p></caption><thead><tr><th scope=\"col\" style=\"text-align: center; vertical-align: bottom;\">City Area</th><th scope=\"col\" style=\"text-align: center; vertical-align: bottom;\">Percent of area&rsquo;s residents in favor of adding more bike paths</th></tr></thead><tbody><tr><th scope=\"row\" style=\"text-align: left;\">North East</th><td style=\"text-align: center;\">12%</td></tr><tr><th scope=\"row\" style=\"text-align: left;\">North Central</th><td style=\"text-align: center;\">26%</td></tr><tr><th scope=\"row\" style=\"text-align: left;\">North West</th><td style=\"text-align: center;\">46%</td></tr><tr><th scope=\"row\" style=\"text-align: left;\">South West</th><td style=\"text-align: center;\">88%</td></tr><tr><th scope=\"row\" style=\"text-align: left;\">South Central</th><td style=\"text-align: center;\">33%</td></tr></tbody></table></figure></p>\n<p>A city&rsquo;s Parks and Recreation department is interested in providing residents with more opportunities for bicycling in their neighborhoods. They&rsquo;re considering adding more bike paths and conducted a survey to understand where demand for more bike paths is highest. The survey indicated the highest level of demand, with 88 percent of the residents interested in adding more bike paths, is in the city&rsquo;s <span aria-hidden=\"true\">______</span><span class=\"sr-only\">blank</span></p>","stem":"<p>Which choice most effectively uses data from the table to complete the statement?</p>","answerOptions":[{"id":"a29ebef1-7c8e-461e-89ce-9b70ed62876f","content":"<p>South West area.</p>"},{"id":"fd9d950c-0449-4582-ba99-7275bca6a8da","content":"<p>South Central area.</p>"},{"id":"4980bd22-dab1-4dda-835d-b63c86407216","content":"<p>North East area.</p>"},{"id":"6e9c6436-668e-4af6-b907-ec5312577d1e","content":"<p>North Central area.</p>"}],"keys":["a29ebef1-7c8e-461e-89ce-9b70ed62876f"],"correct_answer":["A"],"rationale":"<p>Choice A is the best answer because it most effectively uses data from the table to complete the statement about the bike path survey. The table presents the percent of residents from five city areas who are in favor of adding more bike paths. With 88 percent of residents in favor of adding bike paths, the city&rsquo;s South West area has the highest level of demand.&nbsp;</p><p>Choice B is incorrect because, according to the data in the table, 33 percent of residents in the South Central area of the city are in favor of additional bike paths. The area of the city that has 88 percent of its surveyed residents in favor of additional bike paths will best complete the statement. Choice C is incorrect because, according to the data in the table, 12 percent of residents in the North East area of the city are in favor of additional bike paths. The area of the city that has 88 percent of its surveyed residents in favor of additional bike paths will best complete the statement. Choice D is incorrect because, according to the data in the table, 26 percent of residents in the North Central area of the city are in favor of additional bike paths. The area of the city that has 88 percent of its surveyed residents in favor of additional bike paths will best complete the statement. </p>","parenttemplatename":"OSP-KA-QUA-E007","parenttemplateid":"","templateclusterid":"d06994b9-3661-4d3a-baa5-664c1f52056a","templateclustername":"","origin":"proteus","position":"0","createDate":1691007959369,"updateDate":1691007959369}$SATQ$::jsonb, 1691007959369, 1691007959369),
    ($SATQ$fbb84fb0$SATQ$, $SATQ$c1854738-41cb-44ba-be7e-081b7dfd9993$SATQ$::uuid, $SATQ$30554a8a-741f-49bf-885e-e322cd4fdad1$SATQ$::uuid, NULL, $SATQ$qbank$SATQ$, $SATQ$SAT$SATQ$, 1, $SATQ$Reading and Writing$SATQ$, $SATQ$Information and Ideas$SATQ$, $SATQ$INI$SATQ$, $SATQ$COE$SATQ$, $SATQ$Command of Evidence$SATQ$, $SATQ$M$SATQ$, 4, $SATQ$mcq$SATQ$, $SATQ$<p><em>Hedda Gabler </em>is an 1890 play by Henrik Ibsen. As a woman in the Victorian era, Hedda, the play&rsquo;s central character, is unable to freely determine her own future. Instead, she seeks to influence another person&rsquo;s fate, as is evident when she says to another character, <span aria-hidden="true">______</span><span class="sr-only">blank</span></p>$SATQ$, $SATQ$<p>Which quotation from a translation of <em>Hedda Gabler</em> most effectively illustrates the claim?</p>$SATQ$, $SATQ$[{"id":"cefce95e-9e61-4682-aba1-466307edf186","content":"<p>&ldquo;Then what in heaven&rsquo;s name would you have me do with myself?&rdquo;</p>"},{"id":"4d97a4b2-4722-4204-9566-f03acc885acf","content":"<p>&ldquo;I want for once in my life to have power to mould a human destiny.&rdquo;</p>"},{"id":"b327eed2-19f8-4864-aafa-00ee1548e2ba","content":"<p>&ldquo;Then I, poor creature, have no sort of power over you?&rdquo;</p>"},{"id":"336e640b-b92b-41cd-b574-2e6501404bd0","content":"<p>&ldquo;Faithful to your principles, now and for ever! Ah, that is how a man should be!&rdquo;</p>"}]$SATQ$::jsonb, $SATQ$["B"]$SATQ$::jsonb, $SATQ$["4d97a4b2-4722-4204-9566-f03acc885acf"]$SATQ$::jsonb, $SATQ$<p>Choice B is the best answer because it most effectively illustrates the claim in the text that Hedda seeks to influence another character&rsquo;s fate. In the quotation, Hedda says that she wants &ldquo;to have power to mould a human destiny,&rdquo; or shape a person&rsquo;s fate, just as the text indicates. Additionally, the phrase &ldquo;for once in my life&rdquo; suggests that Hedda feels that she has never been able to shape anyone&rsquo;s life, including her own, supporting the text&rsquo;s assertion that she &ldquo;is unable to freely determine her own future.&rdquo; </p><p>Choice A is incorrect because this quotation shows Hedda being uncertain about what to do with her own life, not wanting to influence another person&rsquo;s fate.&nbsp;Choice C is incorrect because while this quotation shows Hedda&rsquo;s interest in finding out whether she has any power over another character, it doesn&rsquo;t clearly show that she wants to influence that person&rsquo;s fate. In this quotation, Hedda seems to have inferred or concluded (&ldquo;then&rdquo;) that she doesn&rsquo;t have any influence over the person to whom she&rsquo;s speaking, and she&rsquo;s asking that person to confirm her lack of influence.&nbsp;Choice D is incorrect because this quotation expresses Hedda&rsquo;s belief that a man should be true to his principles, not her desire to influence another person&rsquo;s fate.&nbsp;</p>$SATQ$, false, 0, $SATQ$OSP-412-LIT$SATQ$, $SATQ$$SATQ$, $SATQ$f2a612d4-42c9-4af3-b535-6a6d7b1bc61d$SATQ$::uuid, $SATQ$$SATQ$, $SATQ$proteus$SATQ$, $SATQ$0$SATQ$, NULL, NULL, $SATQ${"questionId":"fbb84fb0","external_id":"c1854738-41cb-44ba-be7e-081b7dfd9993","vaultid":"30554a8a-741f-49bf-885e-e322cd4fdad1","uId":"eac70bba-87d8-4859-9c49-2ab921335676","program":"SAT","test_type":1,"test_type_desc":"Reading and Writing","primary_class_cd":"INI","domain":"Information and Ideas","skill_cd":"COE","skill_desc":"Command of Evidence","difficulty":"M","score_band_range_cd":4,"type":"mcq","stimulus":"<p><em>Hedda Gabler </em>is an 1890 play by Henrik Ibsen. As a woman in the Victorian era, Hedda, the play&rsquo;s central character, is unable to freely determine her own future. Instead, she seeks to influence another person&rsquo;s fate, as is evident when she says to another character, <span aria-hidden=\"true\">______</span><span class=\"sr-only\">blank</span></p>","stem":"<p>Which quotation from a translation of <em>Hedda Gabler</em> most effectively illustrates the claim?</p>","answerOptions":[{"id":"cefce95e-9e61-4682-aba1-466307edf186","content":"<p>&ldquo;Then what in heaven&rsquo;s name would you have me do with myself?&rdquo;</p>"},{"id":"4d97a4b2-4722-4204-9566-f03acc885acf","content":"<p>&ldquo;I want for once in my life to have power to mould a human destiny.&rdquo;</p>"},{"id":"b327eed2-19f8-4864-aafa-00ee1548e2ba","content":"<p>&ldquo;Then I, poor creature, have no sort of power over you?&rdquo;</p>"},{"id":"336e640b-b92b-41cd-b574-2e6501404bd0","content":"<p>&ldquo;Faithful to your principles, now and for ever! Ah, that is how a man should be!&rdquo;</p>"}],"keys":["4d97a4b2-4722-4204-9566-f03acc885acf"],"correct_answer":["B"],"rationale":"<p>Choice B is the best answer because it most effectively illustrates the claim in the text that Hedda seeks to influence another character&rsquo;s fate. In the quotation, Hedda says that she wants &ldquo;to have power to mould a human destiny,&rdquo; or shape a person&rsquo;s fate, just as the text indicates. Additionally, the phrase &ldquo;for once in my life&rdquo; suggests that Hedda feels that she has never been able to shape anyone&rsquo;s life, including her own, supporting the text&rsquo;s assertion that she &ldquo;is unable to freely determine her own future.&rdquo; </p><p>Choice A is incorrect because this quotation shows Hedda being uncertain about what to do with her own life, not wanting to influence another person&rsquo;s fate.&nbsp;Choice C is incorrect because while this quotation shows Hedda&rsquo;s interest in finding out whether she has any power over another character, it doesn&rsquo;t clearly show that she wants to influence that person&rsquo;s fate. In this quotation, Hedda seems to have inferred or concluded (&ldquo;then&rdquo;) that she doesn&rsquo;t have any influence over the person to whom she&rsquo;s speaking, and she&rsquo;s asking that person to confirm her lack of influence.&nbsp;Choice D is incorrect because this quotation expresses Hedda&rsquo;s belief that a man should be true to his principles, not her desire to influence another person&rsquo;s fate.&nbsp;</p>","parenttemplatename":"OSP-412-LIT","parenttemplateid":"","templateclusterid":"f2a612d4-42c9-4af3-b535-6a6d7b1bc61d","templateclustername":"","origin":"proteus","position":"0","createDate":1691007959336,"updateDate":1691007959336}$SATQ$::jsonb, 1691007959336, 1691007959336),
    ($SATQ$fc1259dd$SATQ$, $SATQ$4fdc5738-b231-4673-a094-37aa2e2ef332$SATQ$::uuid, NULL, NULL, $SATQ$qbank$SATQ$, $SATQ$SAT$SATQ$, 1, $SATQ$Reading and Writing$SATQ$, $SATQ$Information and Ideas$SATQ$, $SATQ$INI$SATQ$, $SATQ$INF$SATQ$, $SATQ$Inferences$SATQ$, $SATQ$E$SATQ$, 2, $SATQ$mcq$SATQ$, $SATQ$<p>Archaeologist Christiana Kohler and her team excavated the Egyptian tomb of Queen Merneith, the wife of a First Dynasty pharaoh. Some scholars claim that she also ruled Egypt on her own and was actually the first female pharaoh. The team found a tablet in Merneith&rsquo;s tomb with writing suggesting that she was in charge of the country&rsquo;s treasury and other central offices. Whether Merneith was a pharaoh or not, this discovery supports the idea that Merneith likely <span aria-hidden="true">______</span><span class="sr-only">blank</span></p>$SATQ$, $SATQ$<p>Which choice most logically completes the text?</p>$SATQ$, $SATQ$[{"id":"269e266c-8a1c-46ad-999a-01a9e349d3dd","content":"<p>had an important role in Egypt&rsquo;s government.</p>"},{"id":"9a5a7cef-df40-441c-b2f0-c526636018f5","content":"<p>lived after rather than before the First Dynasty of Egypt.</p>"},{"id":"57de9963-6290-4256-9be5-0fe2810a0abd","content":"<p>traveled beyond Egypt&rsquo;s borders often.</p>"},{"id":"eab7311f-0c31-4ff5-a856-5a0853229b8d","content":"<p>created a new form of writing in Egypt.</p>"}]$SATQ$::jsonb, $SATQ$["A"]$SATQ$::jsonb, $SATQ$["269e266c-8a1c-46ad-999a-01a9e349d3dd"]$SATQ$::jsonb, $SATQ$<p>Choice A is the best answer because it most logically completes the text&rsquo;s discussion of the evidence found in Queen Merneith&rsquo;s tomb. The text begins by mentioning archaeologists&rsquo; efforts to excavate the tomb of Queen Merneith, the wife of a pharaoh who some scholars think was actually the first female pharaoh. The text states that a tablet discovered in her tomb suggests she "was in charge of the country&rsquo;s treasury and other central offices," which supports the idea that she had an important role in Egypt&rsquo;s government.</p><p>Choice B is incorrect because since the text explicitly states that Merneith&rsquo;s husband was a First Dynasty pharaoh, it can be inferred that she lived during the First Dynasty, not after it. Choice C is incorrect because the text does not provide any evidence that Merneith traveled beyond Egypt&rsquo;s borders often. The text is focused on the archaeological discovery in her tomb and the implications about her potential role as a ruler in Egypt but does not mention anything about her traveling habits. Choice D is incorrect because the text does not mention anything about Merneith creating a new form of writing in Egypt. The text discusses the discovery of a tablet with writing suggesting her governmental role but does not imply that this writing represented a new form created by Merneith.</p>$SATQ$, false, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, $SATQ${"questionId":"fc1259dd","external_id":"4fdc5738-b231-4673-a094-37aa2e2ef332","vaultid":null,"uId":"75839609-3e89-42ac-b7f1-c1695c079841","program":"SAT","test_type":1,"test_type_desc":"Reading and Writing","primary_class_cd":"INI","domain":"Information and Ideas","skill_cd":"INF","skill_desc":"Inferences","difficulty":"E","score_band_range_cd":2,"type":"mcq","stimulus":"<p>Archaeologist Christiana Kohler and her team excavated the Egyptian tomb of Queen Merneith, the wife of a First Dynasty pharaoh. Some scholars claim that she also ruled Egypt on her own and was actually the first female pharaoh. The team found a tablet in Merneith&rsquo;s tomb with writing suggesting that she was in charge of the country&rsquo;s treasury and other central offices. Whether Merneith was a pharaoh or not, this discovery supports the idea that Merneith likely <span aria-hidden=\"true\">______</span><span class=\"sr-only\">blank</span></p>","stem":"<p>Which choice most logically completes the text?</p>","answerOptions":[{"id":"269e266c-8a1c-46ad-999a-01a9e349d3dd","content":"<p>had an important role in Egypt&rsquo;s government.</p>"},{"id":"9a5a7cef-df40-441c-b2f0-c526636018f5","content":"<p>lived after rather than before the First Dynasty of Egypt.</p>"},{"id":"57de9963-6290-4256-9be5-0fe2810a0abd","content":"<p>traveled beyond Egypt&rsquo;s borders often.</p>"},{"id":"eab7311f-0c31-4ff5-a856-5a0853229b8d","content":"<p>created a new form of writing in Egypt.</p>"}],"keys":["269e266c-8a1c-46ad-999a-01a9e349d3dd"],"correct_answer":["A"],"rationale":"<p>Choice A is the best answer because it most logically completes the text&rsquo;s discussion of the evidence found in Queen Merneith&rsquo;s tomb. The text begins by mentioning archaeologists&rsquo; efforts to excavate the tomb of Queen Merneith, the wife of a pharaoh who some scholars think was actually the first female pharaoh. The text states that a tablet discovered in her tomb suggests she \"was in charge of the country&rsquo;s treasury and other central offices,\" which supports the idea that she had an important role in Egypt&rsquo;s government.</p><p>Choice B is incorrect because since the text explicitly states that Merneith&rsquo;s husband was a First Dynasty pharaoh, it can be inferred that she lived during the First Dynasty, not after it. Choice C is incorrect because the text does not provide any evidence that Merneith traveled beyond Egypt&rsquo;s borders often. The text is focused on the archaeological discovery in her tomb and the implications about her potential role as a ruler in Egypt but does not mention anything about her traveling habits. Choice D is incorrect because the text does not mention anything about Merneith creating a new form of writing in Egypt. The text discusses the discovery of a tablet with writing suggesting her governmental role but does not imply that this writing represented a new form created by Merneith.</p>","parenttemplatename":null,"parenttemplateid":null,"templateclusterid":null,"templateclustername":null,"origin":null,"position":null,"createDate":1743430669207,"updateDate":1743430669207}$SATQ$::jsonb, 1743430669207, 1743430669207),
    ($SATQ$fc57d569$SATQ$, $SATQ$f446b6c4-fe01-491d-a6d3-c2ecde85de7c$SATQ$::uuid, NULL, NULL, $SATQ$qbank$SATQ$, $SATQ$SAT$SATQ$, 1, $SATQ$Reading and Writing$SATQ$, $SATQ$Information and Ideas$SATQ$, $SATQ$INI$SATQ$, $SATQ$INF$SATQ$, $SATQ$Inferences$SATQ$, $SATQ$M$SATQ$, 4, $SATQ$mcq$SATQ$, $SATQ$<p>In dialects of English spoken in Scotland, the &ldquo;r&rdquo; sound is strongly emphasized when it appears at the end of syllables (as in &ldquo;car&rdquo;) or before other consonant sounds (as in &ldquo;bird&rdquo;). English dialects of the Upland South, a region stretching from Oklahoma to western Virginia, place similar emphasis on &ldquo;r&rdquo; at the ends of syllables and before other consonant sounds. Historical records show that the Upland South was colonized largely by people whose ancestors came from Scotland. Thus, linguists have concluded that <span aria-hidden="true">______</span><span class="sr-only">blank</span></p>$SATQ$, $SATQ$<p>Which choice most logically completes the text?</p>$SATQ$, $SATQ$[{"id":"ec0f78cd-8065-46fa-8072-b8e4ad567d4c","content":"<p>the English dialects spoken in the Upland South acquired their emphasis on the &ldquo;r&rdquo; sound from dialects spoken in Scotland.</p>"},{"id":"1f5ca0d3-5bfc-46c6-a7de-c2196d75f95a","content":"<p>emphasis on the &ldquo;r&rdquo; sound will eventually spread from English dialects spoken in the Upland South to dialects spoken elsewhere.</p>"},{"id":"2e4f5b13-8371-4f8b-b101-6a326854c245","content":"<p>the English dialects spoken in Scotland were influenced by dialects spoken in the Upland South.</p>"},{"id":"55d3f0ea-150a-4d0b-94f1-2d6e954725d2","content":"<p>people from Scotland abandoned their emphasis on the &ldquo;r&rdquo; sound after relocating to the Upland South.</p>"}]$SATQ$::jsonb, $SATQ$["A"]$SATQ$::jsonb, $SATQ$["ec0f78cd-8065-46fa-8072-b8e4ad567d4c"]$SATQ$::jsonb, $SATQ$<p>Choice A is the best answer because it most logically completes the text&rsquo;s discussion of English dialects spoken in Scotland and the Upland South. The text indicates that these dialects share a feature: putting emphasis on the "r" sound when it appears in certain positions in words. The text goes on to state that records indicate the Upland South was colonized largely by people of Scottish ancestry. It is reasonable to assume that the English dialects spoken by these colonizers were influenced by the English dialects spoken by their ancestors in Scotland. It follows, then, that the emphasis on the "r" sound in the dialects in Scotland carried over into the Upland South dialects as they developed&mdash;that is, that the Upland South dialects likely acquired it from dialects spoken in Scotland.</p><p>Choice B is incorrect because the text suggests that Scottish ancestry explains the origin of the emphasis on the "r" sound in English dialects spoken in the Upland South, since that linguistic feature is also found in dialects spoken in Scotland; the text doesn&rsquo;t address any other dialects or suggest that the feature will spread elsewhere. Choice C is incorrect because the text indicates that many Upland South colonizers were the descendants of Scottish people, suggesting that the English dialects spoken by these colonizers had been influenced by the English dialects spoken by the colonizers&rsquo; ancestors in Scotland and had acquired their emphasis on the "r" sound from those ancestors&rsquo; dialects&mdash;not the other way around. Choice D is incorrect because the text indicates that the emphasis on the "r" sound is part of English dialects spoken in the Upland South today, which almost certainly wouldn&rsquo;t be the case if people from Scotland, who were the main colonizers of the Upland South, had eliminated that linguistic feature from their dialects.</p>$SATQ$, false, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, $SATQ${"questionId":"fc57d569","external_id":"f446b6c4-fe01-491d-a6d3-c2ecde85de7c","vaultid":null,"uId":"d6dca1fa-f728-423e-9955-a7cfa38406f2","program":"SAT","test_type":1,"test_type_desc":"Reading and Writing","primary_class_cd":"INI","domain":"Information and Ideas","skill_cd":"INF","skill_desc":"Inferences","difficulty":"M","score_band_range_cd":4,"type":"mcq","stimulus":"<p>In dialects of English spoken in Scotland, the &ldquo;r&rdquo; sound is strongly emphasized when it appears at the end of syllables (as in &ldquo;car&rdquo;) or before other consonant sounds (as in &ldquo;bird&rdquo;). English dialects of the Upland South, a region stretching from Oklahoma to western Virginia, place similar emphasis on &ldquo;r&rdquo; at the ends of syllables and before other consonant sounds. Historical records show that the Upland South was colonized largely by people whose ancestors came from Scotland. Thus, linguists have concluded that <span aria-hidden=\"true\">______</span><span class=\"sr-only\">blank</span></p>","stem":"<p>Which choice most logically completes the text?</p>","answerOptions":[{"id":"ec0f78cd-8065-46fa-8072-b8e4ad567d4c","content":"<p>the English dialects spoken in the Upland South acquired their emphasis on the &ldquo;r&rdquo; sound from dialects spoken in Scotland.</p>"},{"id":"1f5ca0d3-5bfc-46c6-a7de-c2196d75f95a","content":"<p>emphasis on the &ldquo;r&rdquo; sound will eventually spread from English dialects spoken in the Upland South to dialects spoken elsewhere.</p>"},{"id":"2e4f5b13-8371-4f8b-b101-6a326854c245","content":"<p>the English dialects spoken in Scotland were influenced by dialects spoken in the Upland South.</p>"},{"id":"55d3f0ea-150a-4d0b-94f1-2d6e954725d2","content":"<p>people from Scotland abandoned their emphasis on the &ldquo;r&rdquo; sound after relocating to the Upland South.</p>"}],"keys":["ec0f78cd-8065-46fa-8072-b8e4ad567d4c"],"correct_answer":["A"],"rationale":"<p>Choice A is the best answer because it most logically completes the text&rsquo;s discussion of English dialects spoken in Scotland and the Upland South. The text indicates that these dialects share a feature: putting emphasis on the \"r\" sound when it appears in certain positions in words. The text goes on to state that records indicate the Upland South was colonized largely by people of Scottish ancestry. It is reasonable to assume that the English dialects spoken by these colonizers were influenced by the English dialects spoken by their ancestors in Scotland. It follows, then, that the emphasis on the \"r\" sound in the dialects in Scotland carried over into the Upland South dialects as they developed&mdash;that is, that the Upland South dialects likely acquired it from dialects spoken in Scotland.</p><p>Choice B is incorrect because the text suggests that Scottish ancestry explains the origin of the emphasis on the \"r\" sound in English dialects spoken in the Upland South, since that linguistic feature is also found in dialects spoken in Scotland; the text doesn&rsquo;t address any other dialects or suggest that the feature will spread elsewhere. Choice C is incorrect because the text indicates that many Upland South colonizers were the descendants of Scottish people, suggesting that the English dialects spoken by these colonizers had been influenced by the English dialects spoken by the colonizers&rsquo; ancestors in Scotland and had acquired their emphasis on the \"r\" sound from those ancestors&rsquo; dialects&mdash;not the other way around. Choice D is incorrect because the text indicates that the emphasis on the \"r\" sound is part of English dialects spoken in the Upland South today, which almost certainly wouldn&rsquo;t be the case if people from Scotland, who were the main colonizers of the Upland South, had eliminated that linguistic feature from their dialects.</p>","parenttemplatename":null,"parenttemplateid":null,"templateclusterid":null,"templateclustername":null,"origin":null,"position":null,"createDate":1730147323034,"updateDate":1730147323034}$SATQ$::jsonb, 1730147323034, 1730147323034),
    ($SATQ$fcae209f$SATQ$, $SATQ$ed5783a4-0648-4ffc-8549-df56ac9d140e$SATQ$::uuid, NULL, NULL, $SATQ$qbank$SATQ$, $SATQ$SAT$SATQ$, 1, $SATQ$Reading and Writing$SATQ$, $SATQ$Information and Ideas$SATQ$, $SATQ$INI$SATQ$, $SATQ$INF$SATQ$, $SATQ$Inferences$SATQ$, $SATQ$E$SATQ$, 3, $SATQ$mcq$SATQ$, $SATQ$<p>The Nacional tree is a rare variety of cacao. Nacionals were thought to have gone extinct by the twentieth century due to a fungus. This fungus can spread from tree to nearby tree through the air and causes disease. But around 2013, cacao expert Servio Pachard located some of these Nacional trees. The trees were in the Piedra de Plata coastal forest, within a hard-to-reach valley in Ecuador. Conservationists inferred that the Nacional trees in Piedra de Plata might have avoided the diseases that wiped out the other Nacionals because <span aria-hidden="true">______</span><span class="sr-only">blank</span></p>$SATQ$, $SATQ$<p>Which choice most logically completes the text?</p>$SATQ$, $SATQ$[{"id":"a79959de-e501-4445-9ff4-d25249052193","content":"<p>early twentieth-century scientists did not know why so many Nacionals were becoming infected.</p>"},{"id":"2ce5bc83-5898-41c9-855f-60812c4c06e8","content":"<p>the ability of the fungus to travel through the air was only recently discovered.</p>"},{"id":"a2fb467f-8e75-489d-a981-3d73306b7a2f","content":"<p>they were too far from the other Nacional trees infected by the fungus to become infected themselves.</p>"},{"id":"afbed78c-8ec2-4042-9680-ee6126f868fb","content":"<p>the chocolate made from their pods was highly valued.</p>"}]$SATQ$::jsonb, $SATQ$["C"]$SATQ$::jsonb, $SATQ$["a2fb467f-8e75-489d-a981-3d73306b7a2f"]$SATQ$::jsonb, $SATQ$<p>Choice C is the best answer because it most logically completes the text&rsquo;s discussion of the Nacional trees&rsquo; survival in Piedra de Plata. The text states that the fungus that caused Nacional trees elsewhere to become diseased spreads from tree to nearby tree through the air. The text also mentions that the surviving Nacional trees were found in a hard-to-reach valley in Ecuador. Given this information, it&rsquo;s logical to conclude that these trees might have avoided infection because they were geographically isolated from infected Nacional trees, which prevented the airborne fungus from reaching them.</p><p>Choice A is incorrect because early twentieth-century scientists&rsquo; lack of knowledge about the infection that affected many Nacionals doesn&rsquo;t explain how the trees in the Piedra de Plata coastal forest survived. The text is concerned with the physical factors that allowed certain trees to avoid infection, not with scientists&rsquo; understanding of the disease. Choice B is incorrect. Although the text mentions that the fungus spreads through the air, it doesn&rsquo;t indicate when this ability was discovered. Moreover, even if the ability to move through the air was recently discovered, that wouldn&rsquo;t explain how the trees in Piedra de Plata avoided infection in the past. Choice D is incorrect because the value of the chocolate made from Nacional pods doesn&rsquo;t explain how the trees in the Piedra de Plata coastal forest avoided disease. The text focuses on the physical spread of the fungus that caused most Nacionals to become diseased, not on economic factors related to the trees&rsquo; products.</p>$SATQ$, false, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, $SATQ${"questionId":"fcae209f","external_id":"ed5783a4-0648-4ffc-8549-df56ac9d140e","vaultid":null,"uId":"9152faf2-7f32-432a-af9d-04706eea6970","program":"SAT","test_type":1,"test_type_desc":"Reading and Writing","primary_class_cd":"INI","domain":"Information and Ideas","skill_cd":"INF","skill_desc":"Inferences","difficulty":"E","score_band_range_cd":3,"type":"mcq","stimulus":"<p>The Nacional tree is a rare variety of cacao. Nacionals were thought to have gone extinct by the twentieth century due to a fungus. This fungus can spread from tree to nearby tree through the air and causes disease. But around 2013, cacao expert Servio Pachard located some of these Nacional trees. The trees were in the Piedra de Plata coastal forest, within a hard-to-reach valley in Ecuador. Conservationists inferred that the Nacional trees in Piedra de Plata might have avoided the diseases that wiped out the other Nacionals because <span aria-hidden=\"true\">______</span><span class=\"sr-only\">blank</span></p>","stem":"<p>Which choice most logically completes the text?</p>","answerOptions":[{"id":"a79959de-e501-4445-9ff4-d25249052193","content":"<p>early twentieth-century scientists did not know why so many Nacionals were becoming infected.</p>"},{"id":"2ce5bc83-5898-41c9-855f-60812c4c06e8","content":"<p>the ability of the fungus to travel through the air was only recently discovered.</p>"},{"id":"a2fb467f-8e75-489d-a981-3d73306b7a2f","content":"<p>they were too far from the other Nacional trees infected by the fungus to become infected themselves.</p>"},{"id":"afbed78c-8ec2-4042-9680-ee6126f868fb","content":"<p>the chocolate made from their pods was highly valued.</p>"}],"keys":["a2fb467f-8e75-489d-a981-3d73306b7a2f"],"correct_answer":["C"],"rationale":"<p>Choice C is the best answer because it most logically completes the text&rsquo;s discussion of the Nacional trees&rsquo; survival in Piedra de Plata. The text states that the fungus that caused Nacional trees elsewhere to become diseased spreads from tree to nearby tree through the air. The text also mentions that the surviving Nacional trees were found in a hard-to-reach valley in Ecuador. Given this information, it&rsquo;s logical to conclude that these trees might have avoided infection because they were geographically isolated from infected Nacional trees, which prevented the airborne fungus from reaching them.</p><p>Choice A is incorrect because early twentieth-century scientists&rsquo; lack of knowledge about the infection that affected many Nacionals doesn&rsquo;t explain how the trees in the Piedra de Plata coastal forest survived. The text is concerned with the physical factors that allowed certain trees to avoid infection, not with scientists&rsquo; understanding of the disease. Choice B is incorrect. Although the text mentions that the fungus spreads through the air, it doesn&rsquo;t indicate when this ability was discovered. Moreover, even if the ability to move through the air was recently discovered, that wouldn&rsquo;t explain how the trees in Piedra de Plata avoided infection in the past. Choice D is incorrect because the value of the chocolate made from Nacional pods doesn&rsquo;t explain how the trees in the Piedra de Plata coastal forest avoided disease. The text focuses on the physical spread of the fungus that caused most Nacionals to become diseased, not on economic factors related to the trees&rsquo; products.</p>","parenttemplatename":null,"parenttemplateid":null,"templateclusterid":null,"templateclustername":null,"origin":null,"position":null,"createDate":1743430669214,"updateDate":1743430669214}$SATQ$::jsonb, 1743430669214, 1743430669214),
    ($SATQ$fd1095d7$SATQ$, $SATQ$9708e3d0-f36c-434a-88ae-992ed65c47ba$SATQ$::uuid, NULL, NULL, $SATQ$qbank$SATQ$, $SATQ$SAT$SATQ$, 1, $SATQ$Reading and Writing$SATQ$, $SATQ$Information and Ideas$SATQ$, $SATQ$INI$SATQ$, $SATQ$INF$SATQ$, $SATQ$Inferences$SATQ$, $SATQ$H$SATQ$, 6, $SATQ$mcq$SATQ$, $SATQ$<p>To address the susceptibility of materials used in components of high-performance machinery, such as aircraft engines, to creep (deformation that is induced by persistent mechanical stress and that often occurs at elevated temperatures), materials researchers have developed silicon carbide (SiC) fibers for producing aerospace composites. Testing the thermomechanical properties of several commercially available SiC fibers, Ramakrishna <span data-ssml-sub-alias="T">T.</span> Bhatt <span data-ssml-sub-alias="et al">et al.</span> found that in comparison with two polymer-derived SiC fibers, a nitrogen-treated SiC fiber exhibited a lower minimum creep rate, a measure of the rate at which a stress-exposed material deforms at a constant temperature and uniaxial load. The finding suggests that <span aria-hidden="true">______</span><span class="sr-only">blank</span></p>$SATQ$, $SATQ$<p>Which choice most logically completes the text?</p>$SATQ$, $SATQ$[{"id":"59f6131a-a949-48f4-8542-d843ecaadaf3","content":"<p>unlike the two polymer-derived SiC fibers, the nitrogen-treated SiC fiber can substantially inhibit creep, provided that temperatures and loads are consistent.</p>"},{"id":"39836813-cd43-4000-8d54-0d1045969997","content":"<p>the two polymer-derived SiC fibers likely hold similar potential for reducing the creep resistance of materials exposed to stress and elevated temperatures, thus prolonging the life span of aerospace machinery.&nbsp;</p>"},{"id":"65767c28-75b6-4ab3-a570-e39f6fb76d36","content":"<p>composites based on the two polymer-derived SiC fibers have chemical properties that may improve the mechanical and thermal stability of aerospace equipment to a greater extent than do composites based on the nitrogen-treated SiC fiber.</p>"},{"id":"c49684e9-29ed-47d7-bfa0-f5918fd29223","content":"<p>aerospace composites containing the nitrogen-treated SiC fiber may have the ability to withstand mechanical stress for a longer period of time than can aerospace composites containing either of the two polymer-derived SiC fibers.</p>"}]$SATQ$::jsonb, $SATQ$["D"]$SATQ$::jsonb, $SATQ$["c49684e9-29ed-47d7-bfa0-f5918fd29223"]$SATQ$::jsonb, $SATQ$<p>Choice D is the best answer because it most logically completes the text&rsquo;s discussion of silicon carbide (SiC) fibers and creep, or deformation related to ongoing mechanical stress and elevated temperatures. The text states that Bhatt et al. found that a nitrogen-treated SiC fiber had a lower minimum creep rate than two polymer-derived SiC fibers did. Because having a lower creep rate means that the material is slower to deform with exposure to stress, as the text explains, this finding suggests that aerospace composites made with the nitrogen-treated SiC fiber may be able to withstand mechanical stress for a longer period than those made with the other two polymer-derived SiC fibers can.</p><p>Choice A is incorrect because it overstates the implications of the study&rsquo;s findings, which have to do with the rate of a material&rsquo;s deformation under stress, not the absolute degree of deformation. The text states that Bhatt et al. observed that a nitrogen-treated SiC fiber had a lower minimum creep rate than two polymer-derived SiC fibers did, meaning only that it deformed more slowly over time under constant stress, not that it underwent less deformation overall. Choice B is incorrect because the text doesn&rsquo;t establish any similarity between the two polymer-derived SiC fibers other than that both had a higher creep rate than the nitrogen-treated SiC fiber did in Bhatt et al.&rsquo;s study. Moreover, reducing a material&rsquo;s resistance to creep would mean that the material becomes <em>more</em> susceptible to deformation with exposure to stress and elevated temperatures, which would be expected to shorten rather than prolong the lifespan of machinery made with that material. Choice C is incorrect because the text suggests that the stability of aerospace equipment may be better improved by composites containing nitrogen-treated SiC fiber than by composites containing the two polymer-derived SiC fibers, not the other way around. The text indicates that Bhatt et al. observed that the nitrogen-treated SiC fiber had a lower minimum creep rate than the other two fibers did, meaning that it was slower to degrade under exposure to mechanical stress and elevated temperatures&mdash;suggesting that it may remain stable for longer periods.</p>$SATQ$, false, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, $SATQ${"questionId":"fd1095d7","external_id":"9708e3d0-f36c-434a-88ae-992ed65c47ba","vaultid":null,"uId":"51964430-660d-4532-beba-9e92d8a44e04","program":"SAT","test_type":1,"test_type_desc":"Reading and Writing","primary_class_cd":"INI","domain":"Information and Ideas","skill_cd":"INF","skill_desc":"Inferences","difficulty":"H","score_band_range_cd":6,"type":"mcq","stimulus":"<p>To address the susceptibility of materials used in components of high-performance machinery, such as aircraft engines, to creep (deformation that is induced by persistent mechanical stress and that often occurs at elevated temperatures), materials researchers have developed silicon carbide (SiC) fibers for producing aerospace composites. Testing the thermomechanical properties of several commercially available SiC fibers, Ramakrishna <span data-ssml-sub-alias=\"T\">T.</span> Bhatt <span data-ssml-sub-alias=\"et al\">et al.</span> found that in comparison with two polymer-derived SiC fibers, a nitrogen-treated SiC fiber exhibited a lower minimum creep rate, a measure of the rate at which a stress-exposed material deforms at a constant temperature and uniaxial load. The finding suggests that <span aria-hidden=\"true\">______</span><span class=\"sr-only\">blank</span></p>","stem":"<p>Which choice most logically completes the text?</p>","answerOptions":[{"id":"59f6131a-a949-48f4-8542-d843ecaadaf3","content":"<p>unlike the two polymer-derived SiC fibers, the nitrogen-treated SiC fiber can substantially inhibit creep, provided that temperatures and loads are consistent.</p>"},{"id":"39836813-cd43-4000-8d54-0d1045969997","content":"<p>the two polymer-derived SiC fibers likely hold similar potential for reducing the creep resistance of materials exposed to stress and elevated temperatures, thus prolonging the life span of aerospace machinery.&nbsp;</p>"},{"id":"65767c28-75b6-4ab3-a570-e39f6fb76d36","content":"<p>composites based on the two polymer-derived SiC fibers have chemical properties that may improve the mechanical and thermal stability of aerospace equipment to a greater extent than do composites based on the nitrogen-treated SiC fiber.</p>"},{"id":"c49684e9-29ed-47d7-bfa0-f5918fd29223","content":"<p>aerospace composites containing the nitrogen-treated SiC fiber may have the ability to withstand mechanical stress for a longer period of time than can aerospace composites containing either of the two polymer-derived SiC fibers.</p>"}],"keys":["c49684e9-29ed-47d7-bfa0-f5918fd29223"],"correct_answer":["D"],"rationale":"<p>Choice D is the best answer because it most logically completes the text&rsquo;s discussion of silicon carbide (SiC) fibers and creep, or deformation related to ongoing mechanical stress and elevated temperatures. The text states that Bhatt et al. found that a nitrogen-treated SiC fiber had a lower minimum creep rate than two polymer-derived SiC fibers did. Because having a lower creep rate means that the material is slower to deform with exposure to stress, as the text explains, this finding suggests that aerospace composites made with the nitrogen-treated SiC fiber may be able to withstand mechanical stress for a longer period than those made with the other two polymer-derived SiC fibers can.</p><p>Choice A is incorrect because it overstates the implications of the study&rsquo;s findings, which have to do with the rate of a material&rsquo;s deformation under stress, not the absolute degree of deformation. The text states that Bhatt et al. observed that a nitrogen-treated SiC fiber had a lower minimum creep rate than two polymer-derived SiC fibers did, meaning only that it deformed more slowly over time under constant stress, not that it underwent less deformation overall. Choice B is incorrect because the text doesn&rsquo;t establish any similarity between the two polymer-derived SiC fibers other than that both had a higher creep rate than the nitrogen-treated SiC fiber did in Bhatt et al.&rsquo;s study. Moreover, reducing a material&rsquo;s resistance to creep would mean that the material becomes <em>more</em> susceptible to deformation with exposure to stress and elevated temperatures, which would be expected to shorten rather than prolong the lifespan of machinery made with that material. Choice C is incorrect because the text suggests that the stability of aerospace equipment may be better improved by composites containing nitrogen-treated SiC fiber than by composites containing the two polymer-derived SiC fibers, not the other way around. The text indicates that Bhatt et al. observed that the nitrogen-treated SiC fiber had a lower minimum creep rate than the other two fibers did, meaning that it was slower to degrade under exposure to mechanical stress and elevated temperatures&mdash;suggesting that it may remain stable for longer periods.</p>","parenttemplatename":null,"parenttemplateid":null,"templateclusterid":null,"templateclustername":null,"origin":null,"position":null,"createDate":1743430669211,"updateDate":1743430669211}$SATQ$::jsonb, 1743430669211, 1743430669211),
