    </defs><line xmlns="http://www.w3.org/2000/svg" x1="93.40625" y1="96" x2="385" y2="96" fill="none" stroke="#000000" stroke-linecap="round" stroke-linejoin="round" stroke-width="0.9"/><line xmlns="http://www.w3.org/2000/svg" x1="87.40625" y1="96" x2="99.40625" y2="96" fill="none" stroke="#000000" stroke-linecap="round" stroke-linejoin="round" stroke-width="0.9"/><text text-anchor="end" transform="translate(81.40625 102)" fill="#000000" font-size="19.84" font-family="Crimson Text">5</text><line xmlns="http://www.w3.org/2000/svg" x1="93.40625" y1="136" x2="385" y2="136" fill="none" stroke="#000000" stroke-linecap="round" stroke-linejoin="round" stroke-width="0.9"/><line xmlns="http://www.w3.org/2000/svg" x1="87.40625" y1="136" x2="99.40625" y2="136" fill="none" stroke="#000000" stroke-linecap="round" stroke-linejoin="round" stroke-width="0.9"/><text text-anchor="end" transform="translate(81.40625 142)" fill="#000000" font-size="19.84" font-family="Crimson Text">4</text><line xmlns="http://www.w3.org/2000/svg" x1="93.40625" y1="176" x2="385" y2="176" fill="none" stroke="#000000" stroke-linecap="round" stroke-linejoin="round" stroke-width="0.9"/><line xmlns="http://www.w3.org/2000/svg" x1="87.40625" y1="176" x2="99.40625" y2="176" fill="none" stroke="#000000" stroke-linecap="round" stroke-linejoin="round" stroke-width="0.9"/><text text-anchor="end" transform="translate(81.40625 182)" fill="#000000" font-size="19.84" font-family="Crimson Text">3</text><line xmlns="http://www.w3.org/2000/svg" x1="93.40625" y1="216" x2="385" y2="216" fill="none" stroke="#000000" stroke-linecap="round" stroke-linejoin="round" stroke-width="0.9"/><line xmlns="http://www.w3.org/2000/svg" x1="87.40625" y1="216" x2="99.40625" y2="216" fill="none" stroke="#000000" stroke-linecap="round" stroke-linejoin="round" stroke-width="0.9"/><text text-anchor="end" transform="translate(81.40625 222)" fill="#000000" font-size="19.84" font-family="Crimson Text">2</text><line xmlns="http://www.w3.org/2000/s